func NewUpsertPayload(body *UpsertRequestBody, sessionToken *string) *platformaiscantargets.UpsertPayload {
	v := &platformaiscantargets.UpsertPayload{
		ID:              *body.ID,
		DisplayName:     *body.DisplayName,
		Category:        *body.Category,
		VersionPlistKey: body.VersionPlistKey,
		Reason:          body.Reason,
	}
	if body.Enabled != nil {
		v.Enabled = *body.Enabled
	}
	v.Signatures = unmarshalAiScanTargetSignaturesRequestBodyToPlatformaiscantargetsAiScanTargetSignatures(body.Signatures)
	if body.Enabled == nil {
		v.Enabled = true
	}
	v.SessionToken = sessionToken

	return v
}

